mapper.update:
update bytecode_transformation_metadata
   set bytecode_hash = #{bytecodeHash}, size_bytes = #{sizeBytes},
       transformation_status = #{transformationStatus}, diagnostics_json = #{diagnosticsJson},
       observed_at = #{observedAt}, updated_at = #{updatedAt}
 where runtime_instance_id = #{runtimeInstanceId} and agent_id = #{agentId}
   and binary_class_name = #{binaryClassName} and class_loader_id = #{classLoaderId}
   and revision = #{revision} and snapshot_kind = #{snapshotKind}

mapper.select:
select runtime_instance_id, agent_id, binary_class_name, class_loader_id, revision,
       snapshot_kind, bytecode_hash, size_bytes, transformation_status, diagnostics_json,
       observed_at, created_at, updated_at
  from bytecode_transformation_metadata
 where runtime_instance_id = #{runtimeInstanceId}
   and binary_class_name = #{binaryClassName}
   and class_loader_id = #{classLoaderId}
 order by revision desc, snapshot_kind, agent_id
